"""Build the two German static exercise pages and their small landing page."""
from pathlib import Path
r=Path(__file__).resolve().parents[1]/'docs'
nav='''<header class="topbar"><nav class="nav" aria-label="Hauptnavigation"><a class="brand" href="index.html">KARTOGRAPHIE · HS MAINZ</a><div class="navlinks"><a href="bertin.html" {bertin}>01 · Visuelle Variablen</a><a href="farben.html" {color}>02 · Farben</a></div></nav></header>'''
def range_input(key,label,value,lo,hi,step=1):
 return f'<label for="{key}" class="range-label"><span>{label}</span><output for="{key}" id="{key}-value">{value}</output></label><input id="{key}" data-key="{key}" type="range" min="{lo}" max="{hi}" step="{step}" value="{value}">'
def select(key,label,options):
 return f'<label for="{key}">{label}</label><select id="{key}" data-key="{key}">'+''.join(f'<option value="{v}">{t}</option>' for v,t in options)+'</select>'
def check(key,label):return f'<label class="check"><input type="checkbox" id="{key}" data-key="{key}">{label}</label>'
def group(title,content):return '<div class="control-group"><h3>'+title+'</h3>'+content+'</div>'
bertin_controls=''.join([
 group('Größe',range_input('size','Symbolfläche',155,8,200)+select('sizeMode','Zuordnung',[('same','Einheitlich'),('category','Nach Kategorie')])),
 group('Helligkeit',range_input('light','Helligkeit',.43,.2,.88,.02)+select('lightMode','Zuordnung',[('same','Einheitlich'),('category','Nach Kategorie')])),
 group('Farbton',select('palette','Kategorienfarben',[('bright','Grell'),('editorial','Vier Farbtöne'),('single','Ein Farbton')])),
 group('Form',select('form','Zeichen',[('mixed','Verschiedene Formen'),('circle','Kreise'),('triangle','Dreiecke')])),
 group('Orientierung',range_input('angle','Drehwinkel',40,0,180,5)+check('directions','Richtung je Kategorie')+'<p class="micro">An Kreisen ist eine Drehung unsichtbar.</p>'),
 group('Textur',check('texture','Muster für Symbole')+range_input('density','Musterdichte',3,1,4))])
color_controls=''.join([
 group('Klassifikation',select('method','Methode',[('quantile','Quantile'),('equal','Equal Interval'),('jenks','Jenks (Fisher-Jenks)')])+range_input('classes','Klassen',7,3,7)),
 group('Farben',select('palette','Farbpalette',[('category','Qualitativ · Kategorien'),('warm','Sequenziell · Orange–Rot'),('blue','Sequenziell · Blau'),('viridis','Sequenziell · Viridis'),('diverging','Divergierend · Rot–Blau')])+check('reverse','Reihenfolge umkehren')),
 group('Lesbarkeit',range_input('contrast','Farbkontrast',1,.15,1,.05)+check('gray','Graustufen prüfen')),
 group('Kartendetails',range_input('border','Randlinien',.25,0,.65,.05)+check('names','Orientierungsnamen'))])
configs={
 'bertin':dict(file='bertin.html',number='1',time='20',title='Welche Zeichen helfen beim Lesen?',subtitle='Vier Einrichtungstypen in Mainz: Schulen, Kitas, Bibliotheken und Sportzentren. Links ist ein problematischer Entwurf. Entwickeln Sie rechts eine klarere Karte.',tasks=[('Diagnose','Nennen Sie zwei Probleme. Was fällt zuerst auf? Sind die vier Typen schnell erkennbar?'),('Redesign','Testen Sie die sechs Variablen. Behalten Sie nur Unterschiede, die der Leserfrage helfen.'),('Begründung','Erklären Sie drei Änderungen. Welche Information lässt sich jetzt leichter erkennen?')],controls=bertin_controls,note='Die Einrichtungstypen sind nominale Kategorien. Unterschiedliche Größen und Helligkeiten kodieren hier nur den Typ, keine Kapazität oder Qualität. Orientierung ist keine reale Bewegungsrichtung; Texturen unterscheiden Einrichtungstypen innerhalb der Symbole.',context='<label for="background">Hintergrundkontrast <input id="background" data-key="background" type="range" min="0.05" max="1" step="0.05" value="0.95"><output id="background-value">0.95</output></label>'+check('names','Orientierungsnamen')),
 'color':dict(file='farben.html',number='2',time='18',title='Welche Farben erzählen die Daten richtig?',subtitle='Die Wohnbevölkerung in Mainz im 100-Meter-Gitter. Verbessern Sie die rechte Karte so, dass Mengenunterschiede und räumliche Muster verständlich werden.',tasks=[('Klassifikation','Gleiche Palette, gleiche Klassenanzahl: Vergleichen Sie Equal Interval, Quantile und Jenks.'),('Farben','Klassifikation festhalten: Vergleichen Sie Farbpaletten und Kontrast. Prüfen Sie Graustufen.'),('Begründung','Wählen Sie Ihre bevorzugte Fassung. Erklären Sie die Klassifikation und zwei Farbentscheidungen.')],controls=color_controls,note='Personen je vollständiger 100 × 100-m-Zelle; Stichtag 15.05.2022. Fehlende Zellen sind keine gesicherten Nullwerte. Bei gebundenen Werten können Quantile weniger Klassen ergeben. Die effektive Anzahl steht im Kartentitel.',context='')}
for kind,c in configs.items():
 tasks=''.join(f'<div class="task"><span class="step">{i}</span><div><b>{title}</b><p>{body}</p></div></div>' for i,(title,body) in enumerate(c['tasks'],1))
 cards=''
 for side,title,subtitle in [('left','Ausgangskarte','Diese Gestaltung bleibt unverändert.'),('right','Ihre Überarbeitung','Jede Einstellung wird direkt angewendet.')]:
  buttons='' if side=='left' else '<div class="actions"><button class="btn" id="reset" type="button">↶ Zurücksetzen</button><button class="btn primary" id="export-svg" type="button">SVG ↓</button><button class="btn" id="export-png" type="button">PNG ↓</button></div>'
  cards+=f'<section class="map-card {"original" if side=="left" else "edited"}"><div class="map-toolbar"><div class="map-label"><strong>{title}</strong><span>{subtitle}</span></div>{buttons}</div><svg id="map-{side}" class="map-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 680" role="img" aria-label="{title}: Mainz"></svg></section>'
 html=f'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Interaktive Kartographie-Übung mit Mainzer Daten: links analysieren, rechts verbessern."><title>{c['title']} · Kartographie Mainz</title><link rel="stylesheet" href="assets/style.css?v=3"><script src="assets/d3.min.js" defer></script><script type="module" src="assets/app.mjs?v=3"></script></head><body data-lab="{kind}" class="is-loading">{nav.format(bertin='aria-current="page"' if kind=='bertin' else '',color='aria-current="page"' if kind=='color' else '')}<main><section class="hero"><div class="eyebrow">Übung 01 · Teil {c['number']} · ca. {c['time']} Minuten</div><h1>{c['title']}</h1><p>{c['subtitle']}</p></section><section class="tasks" aria-label="Arbeitsauftrag">{tasks}</section><div id="load-message" role="status">Daten werden geladen …</div><section class="controls-panel" aria-label="Rechte Karte gestalten"><div class="controls-heading"><h2>Rechte Karte gestalten</h2><span class="live-state" id="live-state" role="status" aria-live="polite">Direkte Vorschau</span></div><div class="controls {'color-controls' if kind=='color' else ''}">{c['controls']}</div>{'<div class="context-controls">'+c['context']+'</div>' if c['context'] else ''}</section><div class="workspace">{cards}</div><div class="note"><span>↳</span><span><b>Daten richtig lesen.</b> {c['note']}</span></div><section class="discussion"><div><h2>Zeigen und begründen.</h2><p>Melden Sie sich per Handzeichen. Zeigen Sie dem Dozenten beide Karten und begründen Sie Ihre Entscheidungen. Es gibt keine einzige Musterlösung. Keine Datei-Abgabe erforderlich.</p></div><a href="{'farben.html' if kind=='bertin' else 'bertin.html'}">{'Weiter: Farben →' if kind=='bertin' else '← Zurück: Visuelle Variablen'}</a></section></main><footer><p>Hochschule Mainz · Digitale Kartographie · Prof. Dr.-Ing. Yu Feng · Offene Software, keine kostenpflichtige Karten-API.</p><p>© OpenStreetMap contributors · ODbL · Stand 24.10.2026. Bevölkerung: © Statistische Ämter des Bundes und der Länder, 2024 · Zensus 2022 · DL-DE/BY-2.0. Deutschland-Locator: Natural Earth, Public Domain.</p><p><a href="https://github.com/yfeng-hsm/Karto_HS_Mainz">Quellcode und Datenhinweise</a> · <a href="https://www.openstreetmap.org/copyright">OSM-Lizenz</a> · <a href="https://www.govdata.de/dl-de/by-2-0">Zensus-Lizenz</a></p></footer></body></html>'''
 (r/c['file']).write_text(html)
(r/'index.html').write_text('''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kartographie · Hochschule Mainz</title><link rel="stylesheet" href="assets/style.css?v=3"></head><body>'''+nav.format(bertin='',color='')+'''<main class="landing"><div class="eyebrow">Digitale Kartographie · Übung 01 · 45 Minuten</div><section class="hero"><h1>Eine Karte besser machen.</h1><p>Links ein problematischer Entwurf, rechts Ihre Überarbeitung. Erkunden Sie visuelle Variablen, Farben und Klassifikation mit realen Mainzer Daten – direkt im Browser.</p></section><div class="link-cards"><a class="link-card" href="bertin.html"><div class="eyebrow">Teil 1 · 20 Minuten</div><h2>Visuelle Variablen</h2><p>Schulen, Kitas, Bibliotheken und Sportzentren: Wie unterscheiden sich Kategorien verständlich?</p><span>Übung öffnen →</span></a><a class="link-card" href="farben.html"><div class="eyebrow">Teil 2 · 18 Minuten</div><h2>Farben & Klassifikation</h2><p>Wo wohnen die Menschen in Mainz? Vergleichen Sie Farben, Kontrast und Klassengrenzen.</p><span>Übung öffnen →</span></a></div><p>5 Minuten Einstieg · 38 Minuten Gestaltung · 2 Minuten zeigen und begründen. Keine Anmeldung, kein Notebook und keine eigene Programmierung nötig.</p></main><footer>Hochschule Mainz · Prof. Dr.-Ing. Yu Feng · <a href="https://github.com/yfeng-hsm/Karto_HS_Mainz">GitHub</a></footer></body></html>''')
(r/'.nojekyll').touch()
print('Built index.html, bertin.html and farben.html')
